pub fn resolve_trace_symbol(id: u16) -> Option<&'static str> {
    if id == 0 {
        None
    } else {
        TRACE_SYMBOLS.get(usize::from(id)).copied()
    }
}

pub fn trace_symbol_id(value: &str) -> Option<u16> {
    TRACE_SYMBOLS
        .iter()
        .enumerate()
        .skip(1)
        .find_map(|(index, candidate)| {
            (*candidate == value)
                .then(|| u16::try_from(index).ok())
                .flatten()
        })
}
